+                if (lastMatches[i] < target) {
+                    lastMatches[i] = filteredDocIdSetIterators[i].advance(target);
+                    nextDocs.add(lastMatches[i]);
+                }
+            }
+            currentDocID.set(target);
+            return target;
+        }
+
+        @Override
+        public long cost() {
+            return maxDocId;
+        }
