+                    "timestamp",
+                    new EsField("timestamp", DataTypes.DATETIME, Map.of(), true)
+                );
+                yield EvalMapper.toEvaluator(
+                    new DateTrunc(Source.EMPTY, new Literal(Source.EMPTY, Duration.ofHours(24), EsqlDataTypes.TIME_DURATION), timestamp),
